import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.UnlockedRecipes{UnlockType: packet.UnlockedRecipesTypeNewlyUnlocked, Recipes: []string{"minecraft:stick",
# "minecraft:torch"}}
NEWLY_UNLOCKED = bytes.fromhex("02000000020f6d696e6563726166743a737469636b0f6d696e6563726166743a746f726368")

# generated by gophertunnel b8bd735:
# &packet.UnlockedRecipes{UnlockType: packet.UnlockedRecipesTypeRemoveAllUnlocked}
REMOVE_ALL = bytes.fromhex("0400000000")

GOLDENS = [
    pytest.param(
        v2225.UnlockedRecipesPacket(
            packet_type=v2225.UnlockedRecipesPacket.PacketType.NEWLY_UNLOCKED_RECIPES,
            unlocked_recipes=["minecraft:stick", "minecraft:torch"],
        ),
        NEWLY_UNLOCKED,
        id="newly-unlocked",
    ),
    pytest.param(
        v2225.UnlockedRecipesPacket(packet_type=v2225.UnlockedRecipesPacket.PacketType.REMOVE_ALL_UNLOCKED_RECIPES),
        REMOVE_ALL,
        id="remove-all",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_unlocked_recipes_is_packet_199(version):
    assert version.packets[199] is version.UnlockedRecipesPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_unlocked_recipes_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_unlocked_recipes_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
